selector_to_html = {"a[href=\"paddle/README.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u4f7f\u7528 Paddle \u548c FlagCX \u8bad\u7ec3\u6a21\u578b<a class=\"headerlink\" href=\"#paddle-flagcx\" title=\"Link to this heading\">#</a></h1><p>FlagCX \u73b0\u5df2\u4f5c\u4e3a<strong>\u53ef\u9009\u7684\u9ad8\u6027\u80fd\u901a\u4fe1\u540e\u7aef</strong>\u5b8c\u5168\u96c6\u6210\u5230 Paddle \u4e2d\u3002\u6b64\u96c6\u6210\u652f\u6301\u5728\u591a\u79cd\u786c\u4ef6\u5e73\u53f0\u4e0a\u8fdb\u884c\u9ad8\u6548\u7684\u5206\u5e03\u5f0f\u8bad\u7ec3\uff0c\u5305\u62ec\u5728 NVIDIA \u548c Iluvatar GPU \u4e0a\u652f\u6301<strong>\u5f02\u6784\u8bad\u7ec3</strong>\u3002</p><p>\u4f7f\u7528\u4ee5\u4e0b\u6307\u5357\u5feb\u901f\u5f00\u59cb\u4f7f\u7528 Paddle + FlagCX \u8bad\u7ec3\u6a21\u578b\u3002</p>", "a[href=\"flagcx_overview/flagcx-overview.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u6982\u8ff0<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><p>FlagCX \u662f\u4e00\u4e2a\u53ef\u6269\u5c55\u3001\u81ea\u9002\u5e94\u7684\u8de8\u82af\u7247\u901a\u4fe1\u5e93\u3002\u5b83\u4f5c\u4e3a\u4e00\u4e2a\u5e73\u53f0\uff0c\u5f00\u53d1\u8005\u3001\u7814\u7a76\u4eba\u5458\u548c AI \u5de5\u7a0b\u5e08\u53ef\u4ee5\u5728\u5404\u79cd\u9879\u76ee\u4e0a\u8fdb\u884c\u534f\u4f5c\uff0c\u4e3a\u524d\u6cbf AI \u89e3\u51b3\u65b9\u6848\u7684\u5f00\u53d1\u505a\u51fa\u8d21\u732e\uff0c\u5e76\u4e0e\u5168\u7403\u793e\u533a\u5206\u4eab\u4ed6\u4eec\u7684\u5de5\u4f5c\u3002</p><p>FlagCX \u5229\u7528\u539f\u751f\u96c6\u5408\u901a\u4fe1\u5e93\u5728\u5404\u5e73\u53f0\u4e0a\u63d0\u4f9b\u5b8c\u6574\u7684\u5355\u82af\u7247\u901a\u4fe1\u652f\u6301\u3002\u9664\u4e86\u5176\u539f\u751f x-CCL \u96c6\u6210\u5916\uff0cFlagCX \u8fd8\u5f15\u5165\u4e86\u539f\u521b\u7684\u8bbe\u5907\u7f13\u51b2\u533a IPC \u548c\u8bbe\u5907\u7f13\u51b2\u533a RDMA \u6280\u672f\uff0c\u4e3a\u8de8\u82af\u7247\u548c\u5355\u82af\u7247\u573a\u666f\u542f\u7528\u9ad8\u6027\u80fd P2P \u64cd\u4f5c\u3002\u8fd9\u4e9b\u673a\u5236\u53ef\u4ee5\u4e0e\u539f\u751f x-CCL \u540e\u7aef\u65e0\u7f1d\u7ed3\u5408\uff0c\u4e3a\u8de8\u82af\u7247\u96c6\u5408\u901a\u4fe1\u63d0\u4f9b\u4f18\u5316\u6027\u80fd\u3002</p>", "a[href=\"#flagcx\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">FlagCX \u6587\u6863<a class=\"headerlink\" href=\"#flagcx\" title=\"Link to this heading\">#</a></h1><p><a class=\"sd-sphinx-override sd-btn sd-text-wrap sd-btn-primary sd-btn-lg sd-px-4 sd-py-2 sd-fw-bold reference internal\" href=\"getting-started.html\"><span class=\"doc std std-doc\">\u5feb\u901f\u5f00\u59cb</span></a></p>", "a[href=\"user-guide.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u7528\u6237\u6307\u5357<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><h2>\u73af\u5883\u914d\u7f6e<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h2><p>\u53c2\u89c1<a class=\"reference internal\" href=\"getting-started.html\"><span class=\"std std-doc\">\u5feb\u901f\u5f00\u59cb</span></a>\u9875\u9762\u4e2d\u7684\u73af\u5883\u914d\u7f6e\u90e8\u5206\u3002</p>", "a[href=\"getting-started.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u5feb\u901f\u5f00\u59cb<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><h2>\u73af\u5883\u914d\u7f6e<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h2><p><strong>\u5bb9\u5668\u521b\u5efa\u53c2\u8003\u547d\u4ee4\uff1a</strong></p><p>\u6839\u636e\u9700\u8981\u4fee\u6539 <code class=\"docutils literal notranslate\"><span class=\"pre\">&lt;Docker</span> <span class=\"pre\">name&gt;</span> <span class=\"pre\">&lt;mount</span> <span class=\"pre\">directory&gt;</span> <span class=\"pre\">&lt;mount</span> <span class=\"pre\">point&gt;</span></code> \u5e76\u9009\u62e9 <code class=\"docutils literal notranslate\"><span class=\"pre\">&lt;Docker</span> <span class=\"pre\">Image&gt;</span></code>\u3002</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
